UPDATE ward w JOIN tmp_ward_legacy l ON l.code = w.code SET w.legacy_ward_name = l.ward, w.legacy_district_name = l.district, w.legacy_province_name = l.province WHERE w.id > 100000;
DROP TABLE IF EXISTS tmp_ward_legacy;

-- 3. Đơn hàng chưa giao cho GHN: đổi tên phường/tỉnh theo địa chỉ của khách (trước khi địa chỉ được chuyển)
UPDATE `order` o
    JOIN user u ON u.id = o.user_id
    JOIN address a ON a.id = u.address_id
    JOIN ward w ON w.id = a.ward_id AND w.id <= 100000
    JOIN tmp_address_map_ward m ON m.old_code = w.code
    JOIN ward nw ON nw.code = CONCAT('N', m.new_code) AND nw.id > 100000
    JOIN province np ON np.id = nw.province_id
SET o.to_ward_name = nw.name, o.to_province_name = np.name, o.to_district_name = ''
WHERE o.status IN (1, 2) AND o.to_ward_name = w.name
  AND NOT EXISTS (SELECT 1 FROM waybill wb WHERE wb.order_id = o.id);

-- 4. Địa chỉ có phường: chuyển sang phường mới và tỉnh của phường đó
UPDATE address a
    JOIN ward w ON w.id = a.ward_id AND w.id <= 100000
    JOIN tmp_address_map_ward m ON m.old_code = w.code
    JOIN ward nw ON nw.code = CONCAT('N', m.new_code) AND nw.id > 100000
SET a.ward_id = nw.id, a.province_id = nw.province_id, a.district_id = NULL;

-- 5. Địa chỉ chỉ có tỉnh (dữ liệu mẫu): chuyển theo mã GSO của tỉnh cũ
UPDATE address a
    JOIN province p ON p.id = a.province_id AND p.id <= 1000
    JOIN tmp_address_map_province m ON m.old_code = p.code
    JOIN province np ON np.code = CONCAT('N', m.new_code) AND np.id > 1000
SET a.province_id = np.id, a.district_id = NULL;

-- 6. Dọn danh mục cũ
UPDATE address SET ward_id = NULL WHERE ward_id <= 100000;
UPDATE address SET province_id = NULL WHERE province_id <= 1000;
UPDATE address SET district_id = NULL;
DELETE FROM ward WHERE id <= 100000;
DELETE FROM district;
DELETE FROM province WHERE id <= 1000;
DROP TABLE IF EXISTS tmp_address_map_ward;
DROP TABLE IF EXISTS tmp_address_map_province;
